<script setup>
import { ref } from 'vue'; import { useRouter } from 'vue-router'; import { ElMessage } from 'element-plus'; import { useAuthStore } from '../stores/auth'
const username=ref('admin'), password=ref('admin123'), loading=ref(false), router=useRouter(), auth=useAuthStore()
const submit=async()=>{loading.value=true;try{await auth.login(username.value,password.value);router.push('/count')}catch(e){ElMessage.error(e.response?.data?.detail||e.message)}finally{loading.value=false}}
</script>
<template><div class="login-page"><div class="login-art"><div class="brand">PHOTO<br><strong>COUNT</strong></div><p>把重复的计数工作<br>交给图像处理。</p></div><el-form class="login-form panel" @submit.prevent="submit"><h1>欢迎回来</h1><p class="muted">账号由管理员创建，请使用分配的用户名登录。</p><el-form-item><el-input v-model="username" placeholder="用户名" size="large" /></el-form-item><el-form-item><el-input v-model="password" type="password" placeholder="密码" size="large" show-password /></el-form-item><el-button type="primary" size="large" native-type="submit" :loading="loading" style="width:100%">登录</el-button></el-form></div></template>
<style scoped>.login-page{min-height:100vh;min-height:100dvh;display:grid;grid-template-columns:1fr 420px;gap:8%;align-items:center;padding:7vw;background:#173c38;color:white}.login-art{padding:10%;font-family:'Space Grotesk';font-size:clamp(32px,5vw,72px);line-height:1.03}.login-art .brand{font-size:22px;color:#e2b86c;letter-spacing:2px;margin-bottom:22vh}.login-art .brand strong{font-size:32px;color:white}.login-form{color:#18312f;padding:38px}.login-form h1{font-family:'Space Grotesk';font-size:32px;margin-top:0}@media(max-width:720px){.login-page{display:block;padding:36px 20px}.login-art{padding:10px 0 45px;font-size:36px}.login-art .brand{margin-bottom:40px}.login-form{padding:24px}}</style>
